<div class="grid gap-5 md:grid-cols-4"><?php foreach ($stats as $label => $value): ?><div class="rounded-3xl border border-slate-200 bg-white p-6"><p class="text-sm uppercase tracking-wide text-slate-500"><?= e(str_replace('_', ' ', $label)) ?></p><b class="text-4xl"><?= e($value) ?></b></div><?php endforeach; ?></div><section class="mt-8 rounded-3xl border border-slate-200 bg-white p-6"><h2 class="text-2xl font-black">SEO Health Checks</h2><div class="mt-5 grid gap-4 md:grid-cols-3"><?php foreach (['Meta title coverage','Meta description coverage','Schema readiness','Sitemap status','OpenGraph coverage','Canonical consistency'] as $module): ?><div class="rounded-2xl bg-slate-50 p-4 font-semibold"><i class='bx bx-check text-emerald-600'></i> <?= e($module) ?></div><?php endforeach; ?></div></section><section class="mt-8"><h2 class="mb-4 text-2xl font-black">Recent Products</h2><div class="overflow-x-auto"><table class="admin-table"><tr><th>Title</th><th>Category</th><th>Status</th><th>Views</th></tr><?php foreach ($recent as $product): ?><tr><td><?= e($product['name']) ?></td><td><?= e($product['category_name']) ?></td><td><?= e($product['status']) ?></td><td><?= (int) $product['view_count'] ?></td></tr><?php endforeach; ?></table></div></section>
